CustomFunction.Calculation:
// Recursively appends values from a ¶-delimited list to the query's
// bindings array. Call with index = 1 (GetValue is 1-based).
// Used by QueryWhereIn to add N bindings in one pass.
Let
(
[
_bindingCount = JSONGetElement ( query ; "bindingCount" ) ;
_value = GetValue ( values ; index ) ;
_q1 = JSONSetElement ( query ; "bindings[" & _bindingCount & "]" ; _value ; JSONString ) ;
_q2 = JSONSetElement ( _q1 ; "bindingCount" ; _bindingCount + 1 ; JSONNumber )
];
If ( index < valueCount ;
	QueryAppendBindings ( _q2 ; values ; valueCount ; index + 1 ) ;
// ELSE
	_q2
)
)

// Recursively builds the binding argument string for use inside Evaluate().
// Call with index = 0. bindings is the raw JSON array from the query object.
// Each value is wrapped in Quote() to handle special characters safely.
// Example output: "Active" ; "customer" ; "prospect"
// This string is concatenated into the ExecuteSQL Evaluate expression.
Let
(
[
_value = JSONGetElement ( bindings ; "[" & index & "]" ) ;
_quoted = Quote ( _value ) ;
_rest = If ( index + 1 < bindingCount ; " ; " & QueryBuildBindingArgs ( bindings ; bindingCount ; index + 1 ) ; "" )
];
_quoted & _rest
)

// Recursively builds the GROUP BY column list.
// Call with index = 0. groupBys is the raw JSON array from the query object.
// Regular columns are stored as plain JSON strings; raw expressions are stored
// as JSON objects {"type":"raw","sql":"..."} and detected by checking Left(item;1)="{".
// Example output: "\"CONTACT\".\"type\", YEAR(\"Invoice\".\"date\")"
Let
(
[
_item = JSONGetElement ( groupBys ; "[" & index & "]" ) ;
_isObj = Left ( _item ; 1 ) = "{" ;
_type = If ( _isObj ; JSONGetElement ( _item ; "type" ) ; "" ) ;
_col = Case (
	_isObj and Exact ( _type ; "raw" ) ; JSONGetElement ( _item ; "sql" ) ;
	_item
	) ;
_rest = If ( index + 1 < groupByCount ; ", " & QueryBuildGroupBys ( groupBys ; groupByCount ; index + 1 ) ; "" )
];
_col & _rest
)

// Recursively builds N comma-separated ? placeholders for IN clauses.
// Call with index = 0. Example: count=3 → "?, ?, ?"
If ( index + 1 < count ;
	"?, " & QueryBuildInPlaceholders ( count ; index + 1 ) ;
// ELSE
	"?"
)

// Recursively builds the JOIN clause string.
// Call with index = 0. joins is the raw JSON array from the query object.
// Supported types: inner (default), left, right, cross, subJoin, leftSubJoin.
Let
(
[
_join = JSONGetElement ( joins ; "[" & index & "]" ) ;
_type = JSONGetElement ( _join ; "type" ) ;
_table = JSONGetElement ( _join ; "table" ) ;
_first = JSONGetElement ( _join ; "first" ) ;
_operator = JSONGetElement ( _join ; "operator" ) ;
_second = JSONGetElement ( _join ; "second" ) ;
_keyword = Case (
	Exact ( _type ; "left" ) ; "LEFT JOIN" ;
	Exact ( _type ; "right" ) ; "RIGHT JOIN" ;
	Exact ( _type ; "cross" ) ; "CROSS JOIN" ;
	Exact ( _type ; "subJoin" ) ; "INNER JOIN" ;
	Exact ( _type ; "leftSubJoin" ) ; "LEFT JOIN" ;
	"INNER JOIN"
	) ;
_tableExpr = Case (
	Exact ( _type ; "subJoin" ) or Exact ( _type ; "leftSubJoin" ) ;
		"(" & JSONGetElement ( _join ; "sql" ) & ") " & JSONGetElement ( _join ; "alias" ) ;
	_table
	) ;
_onClause = If ( Exact ( _type ; "cross" ) ;
	"" ;
	" ON " & _first & " " & _operator & " " & _second
	) ;
_clause = _keyword & " " & _tableExpr & _onClause ;
_rest = If ( index + 1 < joinCount ; " " & QueryBuildJoins ( joins ; joinCount ; index + 1 ) ; "" )
];
_clause & _rest
)

// Recursively builds a single JSON object from parallel ¶-delimited lists
// of field values and key names. Call with index = 1 and obj = "{}".
// All values are stored as JSONString; numeric/date coercion is left to the caller.
Let
(
[
_key = GetValue ( keys ; index ) ;
_value = GetValue ( fields ; index ) ;
_newObj = JSONSetElement ( obj ; _key ; _value ; JSONString )
];
If ( index < keyCount ;
	QueryBuildJsonRow ( _newObj ; fields ; keys ; keyCount ; index + 1 ) ;
// ELSE
	_newObj
)
)

// Recursively appends row objects to a JSON array.
// rawResult is the ExecuteSQL output with Char(28) field separators and ¶ row separators.
// Call with rowIndex = 1 and result = "[]".
Let
(
[
_rawRow = GetValue ( rawResult ; rowIndex ) ;
_fields = Substitute ( _rawRow ; Char ( 28 ) ; "¶" ) ;
_rowObj = QueryBuildJsonRow ( "{}" ; _fields ; keys ; keyCount ; 1 ) ;
_newResult = JSONSetElement ( result ; "[" & ( rowIndex - 1 ) & "]" ; _rowObj ; JSONObject )
];
If ( rowIndex < rowCount ;
	QueryBuildJsonRows ( _newResult ; rawResult ; rowCount ; keys ; keyCount ; rowIndex + 1 ) ;
// ELSE
	_newResult
)
)

// Recursively builds the ORDER BY column list.
// Call with index = 0. orderBys is the raw JSON array from the query object.
// Supported types: column+direction (default), raw.
// Example output: "\"CONTACT\".\"lastName\" ASC, RAND()"
Let
(
[
_orderBy = JSONGetElement ( orderBys ; "[" & index & "]" ) ;
_type = JSONGetElement ( _orderBy ; "type" ) ;
_clause = Case (
	Exact ( _type ; "raw" ) ;
		JSONGetElement ( _orderBy ; "sql" ) ;
	// default: column direction
	JSONGetElement ( _orderBy ; "column" ) & " " & JSONGetElement ( _orderBy ; "direction" )
	) ;
_rest = If ( index + 1 < orderByCount ; ", " & QueryBuildOrderBys ( orderBys ; orderByCount ; index + 1 ) ; "" )
];
_clause & _rest
)

// Recursively extracts a plain key name from each column expression in a
// ¶-delimited list, for use as JSON object property names.
// Extraction rules (applied to the original input before SQL conversion):
//   Table::Field  →  Field   (FM fully-qualified: take part after ::)
//   Table.field   →  field   (dot notation: take part after the dot)
//   anything else →  as-is   (e.g. *, COUNT(*))
// Call with index = 1.
Let
(
[
_expr = Trim ( GetValue ( columns ; index ) ) ;
_scopePos = Position ( _expr ; "::" ; 1 ; 1 ) ;
_dotPos = Position ( _expr ; "." ; 1 ; 1 ) ;
_key = Case (
	_scopePos > 0 ; Middle ( _expr ; _scopePos + 2 ; Length ( _expr ) ) ;
	_dotPos > 0 ; Middle ( _expr ; _dotPos + 1 ; Length ( _expr ) ) ;
	_expr
	) ;
_rest = If ( index < columnCount ;
	"¶" & QueryBuildSelectKeys ( columns ; columnCount ; index + 1 ) ;
// ELSE
	""
	)
];
_key & _rest
)

// Recursively builds the UNION / UNION ALL clause string.
// Call with index = 0. unions is the raw JSON array from the query object.
// Each union item: {"sql": "SELECT ...", "all": true|false}
// UNION removes duplicates; UNION ALL keeps them.
Let
(
[
_union = JSONGetElement ( unions ; "[" & index & "]" ) ;
_sql = JSONGetElement ( _union ; "sql" ) ;
_all = JSONGetElement ( _union ; "all" ) ;
_keyword = If ( not IsEmpty ( _all ) and _all ; " UNION ALL " ; " UNION " ) ;
_clause = _keyword & _sql ;
_rest = If ( index + 1 < unionCount ; QueryBuildUnions ( unions ; unionCount ; index + 1 ) ; "" )
];
_clause & _rest
)

// Returns "" for the first clause (index = 0),
// " AND " or " OR " for subsequent clauses.
If ( index = 0 ;
	"" ;
// ELSE
	If ( Exact ( boolean ; "or" ) ;
		" OR " ;
	// ELSE
		" AND "
	)
)

// Recursively builds the HAVING clause body (excluding the "HAVING" keyword).
// Call with index = 0. havings is the raw JSON array from the query object.
// Supported types: basic (default), raw.
// OR prefix supported via boolean = "or" on any having object.
Let
(
[
_having = JSONGetElement ( havings ; "[" & index & "]" ) ;
_type = JSONGetElement ( _having ; "type" ) ;
_column = JSONGetElement ( _having ; "column" ) ;
_operator = JSONGetElement ( _having ; "operator" ) ;
_boolean = JSONGetElement ( _having ; "boolean" ) ;
_prefix = QueryBuildWhereBooleanPrefix ( _boolean ; index ) ;
_clause = Case (
	Exact ( _type ; "raw" ) ;
		_prefix & "(" & JSONGetElement ( _having ; "sql" ) & ")" ;
	// default: basic column operator ?
	_prefix & _column & " " & _operator & " ?"
	) ;
_rest = If ( index + 1 < havingCount ; QueryBuildHavings ( havings ; havingCount ; index + 1 ) ; "" )
];
_clause & _rest
)

// Recursively builds the WHERE clause body (excluding the "WHERE" keyword).
// Call with index = 0. wheres is the raw JSON array from the query object.
// Supported types: basic, in, notIn, null, notNull, between, notBetween,
//   column, raw, group, exists, notExists, inSubquery, notInSubquery.
Let
(
[
_where = JSONGetElement ( wheres ; "[" & index & "]" ) ;
_type = JSONGetElement ( _where ; "type" ) ;
_column = JSONGetElement ( _where ; "column" ) ;
_operator = JSONGetElement ( _where ; "operator" ) ;
_boolean = JSONGetElement ( _where ; "boolean" ) ;
_valueCount = JSONGetElement ( _where ; "valueCount" ) ;
_prefix = QueryBuildWhereBooleanPrefix ( _boolean ; index ) ;
_clause = Case (
	Exact ( _type ; "basic" ) ;
		_prefix & _column & " " & _operator & " ?" ;
	Exact ( _type ; "in" ) ;
		_prefix & _column & " IN (" & QueryBuildInPlaceholders ( _valueCount ; 0 ) & ")" ;
	Exact ( _type ; "notIn" ) ;
		_prefix & _column & " NOT IN (" & QueryBuildInPlaceholders ( _valueCount ; 0 ) & ")" ;
	Exact ( _type ; "null" ) ;
		_prefix & _column & " IS NULL" ;
	Exact ( _type ; "notNull" ) ;
		_prefix & _column & " IS NOT NULL" ;
	Exact ( _type ; "between" ) ;
		_prefix & _column & " BETWEEN ? AND ?" ;
	Exact ( _type ; "notBetween" ) ;
		_prefix & _column & " NOT BETWEEN ? AND ?" ;
	Exact ( _type ; "column" ) ;
		_prefix & _column & " " & _operator & " " & JSONGetElement ( _where ; "second" ) ;
	Exact ( _type ; "raw" ) ;
		_prefix & "(" & JSONGetElement ( _where ; "sql" ) & ")" ;
	Exact ( _type ; "group" ) ;
		_prefix & "(" & QueryBuildWheres ( JSONGetElement ( _where ; "wheres" ) ; JSONGetElement ( _where ; "whereCount" ) ; 0 ) & ")" ;
	Exact ( _type ; "exists" ) ;
		_prefix & "EXISTS (" & JSONGetElement ( _where ; "sql" ) & ")" ;
	Exact ( _type ; "notExists" ) ;
		_prefix & "NOT EXISTS (" & JSONGetElement ( _where ; "sql" ) & ")" ;
	Exact ( _type ; "inSubquery" ) ;
		_prefix & _column & " IN (" & JSONGetElement ( _where ; "sql" ) & ")" ;
	Exact ( _type ; "notInSubquery" ) ;
		_prefix & _column & " NOT IN (" & JSONGetElement ( _where ; "sql" ) & ")" ;
	""
	) ;
_rest = If ( index + 1 < whereCount ; QueryBuildWheres ( wheres ; whereCount ; index + 1 ) ; "" )
];
_clause & _rest
)

// Converts a FileMaker fully-qualified field name (Table::Field) to a
// quoted SQL dot-notation identifier ("Table"."Field"). Quote() is used for
// readability and automatic escaping. Expressions without :: pass through
// unchanged, so *, COUNT(*), and already-converted references are safe.
// Callers are responsible for resolving direct field references via GetFieldName()
// before passing to this function.
Let
(
[
_sepPos = Position ( field ; "::" ; 1 ; 1 )
];
If ( _sepPos > 0 ;
	Quote ( Left ( field ; _sepPos - 1 ) ) & "." & Quote ( Middle ( field ; _sepPos + 2 ; Length ( field ) ) ) ;
// ELSE
	field
)
)

// Recursively converts a ¶-delimited column list to SQL column expressions.
// Delegates individual field conversion to QueryFieldFormat.
// Call with index = 1 (GetValue is 1-based).
Let
(
[
_field = Trim ( GetValue ( columns ; index ) ) ;
_converted = QueryFieldFormat ( _field ) ;
_rest = If ( index < columnCount ;
	", " & QueryBuildSelects ( columns ; columnCount ; index + 1 ) ;
// ELSE
	""
	)
];
_converted & _rest
)

// Recursively appends bindings from a JSON array (sourceBindings) into
// outerQuery's bindings array. Call with index = 0.
// Analogous to QueryAppendBindings but reads from a JSON array rather
// than a ¶-delimited list. Used by QueryWhereInSubquery.
Let
(
[
_bindingCount = JSONGetElement ( outerQuery ; "bindingCount" ) ;
_value = JSONGetElement ( sourceBindings ; "[" & index & "]" ) ;
_q1 = JSONSetElement ( outerQuery ; "bindings[" & _bindingCount & "]" ; _value ; JSONString ) ;
_q2 = JSONSetElement ( _q1 ; "bindingCount" ; _bindingCount + 1 ; JSONNumber )
];
If ( index + 1 < sourceCount ;
	QueryMergeBindings ( _q2 ; sourceBindings ; sourceCount ; index + 1 ) ;
// ELSE
	_q2
)
)

// Extracts the body of a named SQL clause from QueryToSQL-formatted output.
// Uses the "Char(29) trick": replace ¶ + 4 spaces with Char(29) so that
// remaining ¶ characters only precede top-level keywords.
// Returns the clause body with Char(29) as internal line separators,
// or "" if the clause is not present.
// Works for SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY, INNER JOIN, etc.
// Does NOT apply to single-line clauses (OFFSET, FETCH FIRST) — parse those directly.
Let
(
[
_norm = Substitute ( sql ; ¶ & "    " ; Char ( 29 ) ) ;
// Clause may be at position 1 (SELECT) or preceded by ¶ (all others)
_atStart = Left ( _norm ; Length ( clauseName ) ) = clauseName ;
_markerPos = Position ( _norm ; ¶ & clauseName ; 1 ; 1 ) ;
_clauseFound = _atStart or _markerPos > 0 ;
_keyStart = Case (
	_atStart ; 1 ;
	_markerPos > 0 ; _markerPos + 1 ;
	0
) ;
// Find first Char(29) after keyword (may have extra text, e.g. "SELECT DISTINCT")
_afterKeyword = _keyStart + Length ( clauseName ) ;
_char29Pos = Position ( _norm ; Char ( 29 ) ; _afterKeyword ; 1 ) ;
_bodyStart = _char29Pos + 1 ;
// Body ends just before next ¶ (next top-level keyword) or at string end
_nextPara = Position ( _norm ; ¶ ; _bodyStart ; 1 ) ;
_end = If ( _nextPara > 0 ; _nextPara - 1 ; Length ( _norm ) ) ;
_body = Middle ( _norm ; _bodyStart ; _end - _bodyStart + 1 )
] ;
If ( not _clauseFound or _char29Pos = 0 ; "" ; _body )
)

// Recursively parses GROUP BY columns from a ¶-delimited list.
// colList: columns extracted from the GROUP BY clause body (one per line).
// index: 1-based.
// Detection: column starts with " (double-quote) → regular column stored as plain string.
// Anything else (function calls etc.) → raw expression stored as {"type":"raw","sql":"..."}.
// This mirrors the storage format expected by QueryBuildGroupBys.
Let
(
[
_col = Trim ( GetValue ( colList ; index ) ) ;
_isQuoted = Left ( _col ; 1 ) = Char ( 34 ) ;
_groupByCount = JSONGetElement ( query ; "groupByCount" ) ;
_item = If ( _isQuoted ;
	_col ;
	JSONSetElement ( "{}" ;
		[ "type" ; "raw" ; JSONString ] ;
		[ "sql" ; _col ; JSONString ]
		)
	) ;
_itemType = If ( _isQuoted ; JSONString ; JSONObject ) ;
_q1 = JSONSetElement ( query ; "groupBys[" & _groupByCount & "]" ; _item ; _itemType ) ;
_q2 = JSONSetElement ( _q1 ; "groupByCount" ; _groupByCount + 1 ; JSONNumber ) ;
_rest = If ( index < count ;
	QueryParseGroupBys ( _q2 ; colList ; count ; index + 1 ) ;
	_q2
	)
] ;
_rest
)

// Detects the type of a single HAVING condition token and appends a having object.
// token: condition text stripped of boolean prefix, trimmed.
// boolean: "and" or "or".
// Supported types (matching QueryBuildHavings):
//   raw   — token starts with "(" (was wrapped by QueryHavingRaw)
//   basic — default: column op ? (one binding)
// Column extraction for basic: strip trailing " ?", find last " to get column,
// everything between last " and the stripped end is the operator.
Let
(
[
_dq = Char ( 34 ) ;
_havingCount = JSONGetElement ( query ; "havingCount" ) ;
_isRaw = Left ( token ; 1 ) = "(" ;
// Basic: "T"."col" op ?  — ends with " ?"
_stripRhs = Left ( token ; Length ( token ) - 2 ) ;
_lastDq = Position ( _stripRhs ; _dq ; 1 ; PatternCount ( _stripRhs ; _dq ) ) ;
_column = Left ( _stripRhs ; _lastDq ) ;
_operator = Trim ( Middle ( _stripRhs ; _lastDq + 1 ; Length ( _stripRhs ) ) ) ;
// Raw: strip outer parens and restore any Char(29) to ¶+4spaces
_rawSql = Substitute ( Middle ( token ; 2 ; Length ( token ) - 2 ) ; Char ( 29 ) ; ¶ & "    " ) ;
_havingObj = If ( _isRaw ;
	JSONSetElement ( "{}" ;
		[ "type" ; "raw" ; JSONString ] ;
		[ "sql" ; _rawSql ; JSONString ] ;
		[ "boolean" ; boolean ; JSONString ]
		) ;
	JSONSetElement ( "{}" ;
		[ "type" ; "basic" ; JSONString ] ;
		[ "column" ; _column ; JSONString ] ;
		[ "operator" ; _operator ; JSONString ] ;
		[ "boolean" ; boolean ; JSONString ]
		)
	) ;
_q1 = JSONSetElement ( query ; "havings[" & _havingCount & "]" ; _havingObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "havingCount" ; _havingCount + 1 ; JSONNumber )
] ;
_q2
)

// Iterates over a ¶-delimited list of HAVING condition tokens.
// Same structure as QueryParseWheresIter but calls QueryParseHavingCondition.
// condList: output of QueryParseSplitBooleans with Char(28) replaced by ¶.
// condCount: ValueCount of condList. index: 1-based.
Let
(
[
_raw = GetValue ( condList ; index ) ;
_isOr  = Left ( _raw ; 4 ) = " OR " ;
_isAnd = Left ( _raw ; 5 ) = " AND " ;
_boolean = If ( _isOr ; "or" ; "and" ) ;
_condition = Trim ( Case (
	_isAnd ; Middle ( _raw ; 6 ; Length ( _raw ) ) ;
	_isOr  ; Middle ( _raw ; 5 ; Length ( _raw ) ) ;
	_raw
	) ) ;
_q1 = QueryParseHavingCondition ( query ; _condition ; _boolean ) ;
_rest = If ( index < condCount ;
	QueryParseHavingsIter ( _q1 ; condList ; condCount ; index + 1 ) ;
	_q1
	)
] ;
_rest
)

// Recursively parses JOIN clauses from a Char(29)-normalised SQL string.
// normSql: sql with ¶+4spaces already replaced by Char(29).
// startPos: position to begin scanning (advance past each parsed JOIN).
// Appends join objects to query.joins and increments joinCount.
// Supports: INNER JOIN, LEFT JOIN, RIGHT JOIN, CROSS JOIN.
// Sub-join types (Phase 3) round-trip as inner/left with the full table expression.
// Call with startPos = 1.
Let
(
[
// Find the next occurrence of each JOIN keyword at a ¶ boundary
_p29 = Char ( 29 ) ;
_posInner = Position ( normSql ; ¶ & "INNER JOIN" & _p29 ; startPos ; 1 ) ;
_posLeft  = Position ( normSql ; ¶ & "LEFT JOIN"  & _p29 ; startPos ; 1 ) ;
_posRight = Position ( normSql ; ¶ & "RIGHT JOIN" & _p29 ; startPos ; 1 ) ;
_posCross = Position ( normSql ; ¶ & "CROSS JOIN" & _p29 ; startPos ; 1 ) ;
// Use 99999999 as "not found" sentinel for Min()
_pI = If ( _posInner > 0 ; _posInner ; 99999999 ) ;
_pL = If ( _posLeft  > 0 ; _posLeft  ; 99999999 ) ;
_pR = If ( _posRight > 0 ; _posRight ; 99999999 ) ;
_pC = If ( _posCross > 0 ; _posCross ; 99999999 ) ;
_minPos = Min ( _pI ; _pL ; _pR ; _pC ) ;
_hasJoin = _minPos < 99999999 ;
// Identify which keyword matched
_keyword = Case (
	_minPos = _posInner ; "INNER JOIN" ;
	_minPos = _posLeft  ; "LEFT JOIN" ;
	_minPos = _posRight ; "RIGHT JOIN" ;
	_minPos = _posCross ; "CROSS JOIN" ;
	""
	) ;
_type = Case (
	_keyword = "LEFT JOIN"  ; "left" ;
	_keyword = "RIGHT JOIN" ; "right" ;
	_keyword = "CROSS JOIN" ; "cross" ;
	"inner"
	) ;
// Body starts after ¶KEYWORD{29}
_bodyStart = _minPos + 1 + Length ( _keyword ) + 1 ;
// Body ends just before the next ¶ or at end of string
_nextPara = Position ( normSql ; ¶ ; _bodyStart ; 1 ) ;
_bodyEnd = If ( _nextPara > 0 ; _nextPara - 1 ; Length ( normSql ) ) ;
_body = Middle ( normSql ; _bodyStart ; _bodyEnd - _bodyStart + 1 ) ;
// Parse: table [ON first op second]
_onPos = Position ( _body ; " ON " ; 1 ; 1 ) ;
_table = If ( _onPos > 0 ; Left ( _body ; _onPos - 1 ) ; _body ) ;
_onClause = If ( _onPos > 0 ; Middle ( _body ; _onPos + 4 ; Length ( _body ) ) ; "" ) ;
// Parse ON clause: "T1"."c1" op "T2"."c2"
// First expression ends at the last " before a space+operator
_dq = Char ( 34 ) ;
_splitPos = Position ( _onClause ; _dq & " " ; 1 ; 1 ) ;
_first = If ( _splitPos > 0 ; Left ( _onClause ; _splitPos ) ; "" ) ;
_afterFirst = If ( _splitPos > 0 ; Trim ( Middle ( _onClause ; _splitPos + 2 ; Length ( _onClause ) ) ) ; "" ) ;
_opEnd = Position ( _afterFirst ; " " ; 1 ; 1 ) ;
_operator = If ( _opEnd > 0 ; Left ( _afterFirst ; _opEnd - 1 ) ; _afterFirst ) ;
_second = If ( _opEnd > 0 ; Trim ( Middle ( _afterFirst ; _opEnd + 1 ; Length ( _afterFirst ) ) ) ; "" ) ;
// Build join object
_joinCount = JSONGetElement ( query ; "joinCount" ) ;
_joinObj = Case (
	Exact ( _type ; "cross" ) ;
		JSONSetElement ( "{}" ;
			[ "type" ; _type ; JSONString ] ;
			[ "table" ; _table ; JSONString ] ;
			[ "first" ; "" ; JSONString ] ;
			[ "operator" ; "" ; JSONString ] ;
			[ "second" ; "" ; JSONString ]
			) ;
	JSONSetElement ( "{}" ;
		[ "type" ; _type ; JSONString ] ;
		[ "table" ; _table ; JSONString ] ;
		[ "first" ; _first ; JSONString ] ;
		[ "operator" ; _operator ; JSONString ] ;
		[ "second" ; _second ; JSONString ]
		)
	) ;
_q1 = JSONSetElement ( query ; "joins[" & _joinCount & "]" ; _joinObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "joinCount" ; _joinCount + 1 ; JSONNumber ) ;
// Recurse: next JOIN starts after the current body
_nextStart = _bodyEnd + 1
] ;
If ( not _hasJoin ;
	query ;
	QueryParseJoins ( _q2 ; normSql ; _nextStart )
)
)

// Recursively parses ORDER BY items from a ¶-delimited list.
// colList: items extracted from the ORDER BY clause body (one per line).
// index: 1-based.
// Detection:
//   ends with " ASC"  → column + direction "ASC"
//   ends with " DESC" → column + direction "DESC"
//   anything else     → type "raw", sql stored as-is
// This mirrors the storage format of QueryOrderBy / QueryOrderByRaw
// (column entries carry no "type" key; QueryBuildOrderBys defaults to column).
Let
(
[
_item = Trim ( GetValue ( colList ; index ) ) ;
_isAsc  = Right ( _item ; 4 ) = " ASC" ;
_isDesc = Right ( _item ; 5 ) = " DESC" ;
_orderByCount = JSONGetElement ( query ; "orderByCount" ) ;
_col = Case (
	_isAsc  ; Left ( _item ; Length ( _item ) - 4 ) ;
	_isDesc ; Left ( _item ; Length ( _item ) - 5 ) ;
	_item
	) ;
_dir = Case (
	_isAsc  ; "ASC" ;
	_isDesc ; "DESC" ;
	""
	) ;
_obj = Case (
	_isAsc or _isDesc ;
		JSONSetElement ( "{}" ;
			[ "column" ; _col ; JSONString ] ;
			[ "direction" ; _dir ; JSONString ]
			) ;
	JSONSetElement ( "{}" ;
		[ "type" ; "raw" ; JSONString ] ;
		[ "sql" ; _item ; JSONString ]
		)
	) ;
_q1 = JSONSetElement ( query ; "orderBys[" & _orderByCount & "]" ; _obj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "orderByCount" ; _orderByCount + 1 ; JSONNumber ) ;
_rest = If ( index < count ;
	QueryParseOrderBys ( _q2 ; colList ; count ; index + 1 ) ;
	_q2
	)
] ;
_rest
)

// Extracts a plain JSON property key name from a SQL column expression.
// Rules (applied to SQL-formatted expressions):
//   expr AS alias          →  alias   (anything with AS)
//   "Table"."Field"        →  Field   (unquote the last identifier)
//   "Field"                →  Field   (single quoted identifier)
//   *  /  COUNT(*)  etc.   →  as-is
// Used by QueryParseSelectKeysSQL to build the selectKeys ¶-list.
Let
(
[
_expr = Trim ( expr ) ;
_dq = Char ( 34 ) ;
_dotPattern = _dq & "." & _dq ;
_asPos = Position ( _expr ; " AS " ; 1 ; 1 ) ;
_dotCount = PatternCount ( _expr ; _dotPattern ) ;
_lastDotPos = If ( _dotCount > 0 ; Position ( _expr ; _dotPattern ; 1 ; _dotCount ) ; 0 ) ;
// For a plain "Field" (starts and ends with "), strip outer quotes
_isSingleQuoted = Left ( _expr ; 1 ) = _dq and Right ( _expr ; 1 ) = _dq and _dotCount = 0
] ;
Case (
	_asPos > 0 ;
		Trim ( Middle ( _expr ; _asPos + 4 ; Length ( _expr ) ) ) ;
	_lastDotPos > 0 ;
		// "Table"."Field" → extract Field (between last "." and trailing ")
		Middle ( _expr ; _lastDotPos + 3 ; Length ( _expr ) - _lastDotPos - 3 ) ;
	_isSingleQuoted ;
		Middle ( _expr ; 2 ; Length ( _expr ) - 2 ) ;
	_expr
)
)

// Recursively extracts JSON property key names from a ¶-delimited list of
// SQL column expressions (already in SQL form, e.g. "Table"."Field").
// Delegates single-expression extraction to QueryParseSelectKey.
// Call with index = 1.
Let
(
[
_expr = Trim ( GetValue ( colList ; index ) ) ;
_key = QueryParseSelectKey ( _expr ) ;
_rest = If ( index < count ;
	"¶" & QueryParseSelectKeysSQL ( colList ; count ; index + 1 ) ;
	""
	)
] ;
_key & _rest
)

// Parses the SELECT clause from QueryToSQL output.
// Populates: selects (comma-separated SQL expressions), selectKeys (¶-list of
// plain key names for QueryGetResultsAsJson), and distinct flag.
// QueryToSQL formats SELECT columns as col1,¶    col2,¶    col3.
// After QueryParseClause (which applies the Char(29) trick), columns are
// separated by ,Char(29). Replacing ,Char(29) with ¶ gives one column per line.
Let
(
[
_distinct = PatternCount ( sql ; "SELECT DISTINCT" & ¶ ) > 0 ;
_body = QueryParseClause ( sql ; "SELECT" ) ;
// Each column boundary is marked as ,{29} in the clause body
_colList = Substitute ( _body ; "," & Char ( 29 ) ; ¶ ) ;
_colCount = ValueCount ( _colList ) ;
// Rejoin with ", " to store as the selects string
_selects = Substitute ( _colList ; ¶ ; ", " ) ;
// Extract plain key names for QueryGetResultsAsJson
_selectKeys = If ( Trim ( _colList ) = "*" ;
	"*" ;
	QueryParseSelectKeysSQL ( _colList ; _colCount ; 1 )
	) ;
_q1 = JSONSetElement ( query ; "selects" ; _selects ; JSONString ) ;
_q2 = JSONSetElement ( _q1 ; "selectKeys" ; _selectKeys ; JSONString ) ;
_q3 = If ( _distinct ; JSONSetElement ( _q2 ; "distinct" ; 1 ; JSONBoolean ) ; _q2 )
] ;
_q3
)

// Depth-aware recursive scanner. Inserts Char(28) before top-level " AND " / " OR ".
// Tracks parenthesis depth so AND/OR inside (...) are NOT marked.
// Call with depth=0, pos=1, accumulator="".
// Output: text with Char(28) before each top-level AND/OR separator.
// Split result: Substitute(result ; Char(28) ; ¶) then GetValue.
// Each value after the first starts with " AND " or " OR " (boolean prefix).
// FM recursion limit ~10,000 steps → handles ~5,000-char WHERE clauses.
Let
(
[
_len = Length ( text ) ;
_char = Middle ( text ; pos ; 1 ) ;
_isAnd = depth = 0 and Middle ( text ; pos ; 5 ) = " AND " ;
_isOr = depth = 0 and Middle ( text ; pos ; 4 ) = " OR " ;
_newDepth = Case (
	_char = "(" ; depth + 1 ;
	_char = ")" ; depth - 1 ;
	depth
)
] ;
If ( pos > _len ;
	accumulator ;
	Case (
		_isAnd ;
			QueryParseSplitBooleans ( text ; depth ; pos + 5 ; accumulator & Char ( 28 ) & " AND " ) ;
		_isOr ;
			QueryParseSplitBooleans ( text ; depth ; pos + 4 ; accumulator & Char ( 28 ) & " OR " ) ;
		QueryParseSplitBooleans ( text ; _newDepth ; pos + 1 ; accumulator & _char )
	)
)
)

// Parses the HAVING clause from QueryToSQL output.
// Same approach as QueryParseWheres: extract body via QueryParseClause,
// reconstruct AND/OR from Char(29) markers, split depth-aware, iterate.
// HAVING supports: basic (col op ?) and raw (wrapped in parens).
// No BETWEEN fix needed for HAVING (BETWEEN is not a HAVING type).
Let
(
[
_body = QueryParseClause ( sql ; "HAVING" ) ;
_havingText = Substitute ( Substitute ( _body ;
	Char ( 29 ) & "AND" & Char ( 29 ) ; " AND " ) ;
	Char ( 29 ) & "OR" & Char ( 29 ) ; " OR " ) ;
_split = QueryParseSplitBooleans ( _havingText ; 0 ; 1 ; "" ) ;
_condList = Substitute ( _split ; Char ( 28 ) ; ¶ ) ;
_condCount = ValueCount ( _condList )
] ;
If ( IsEmpty ( _body ) ;
	query ;
	QueryParseHavingsIter ( query ; _condList ; _condCount ; 1 )
)
)

// Depth-aware recursive scanner. Inserts Char(28) before each top-level comma.
// Tracks parenthesis depth so commas inside (...) are NOT marked.
// Call with depth=0, pos=1, accumulator="".
// Output: text with Char(28) before each top-level comma.
// Split result: Substitute(result ; Char(28) ; ¶) then GetValue.
Let
(
[
_len = Length ( text ) ;
_char = Middle ( text ; pos ; 1 ) ;
_isComma = depth = 0 and _char = "," ;
_newDepth = Case (
	_char = "(" ; depth + 1 ;
	_char = ")" ; depth - 1 ;
	depth
)
] ;
If ( pos > _len ;
	accumulator ;
	If ( _isComma ;
		QueryParseSplitComma ( text ; depth ; pos + 1 ; accumulator & Char ( 28 ) ) ;
		QueryParseSplitComma ( text ; _newDepth ; pos + 1 ; accumulator & _char )
	)
)
)

// Detects the type of a single WHERE condition token and appends a where object.
// token: the condition text, stripped of any leading AND/OR prefix, trimmed.
// boolean: "and" or "or".
// Restores Char(29) → ¶+4spaces within extracted sql strings (for round-tripping
// subquery conditions that may contain multi-line inner SQL).
// Detection priority (matches the order in QueryBuildWheres rendering):
//   notExists, exists, notNull, null,
//   notInSubquery, inSubquery, notIn, in,
//   notBetween, between, raw (starts with "("), column (ends with "), basic.
// Phase 2 adds: group (outer parens with AND/OR inside at depth 0).
Let
(
[
_dq = Char ( 34 ) ;
_restoreChar29 = ¶ & "    " ;
_whereCount = JSONGetElement ( query ; "whereCount" ) ;
// --- Type detection ---
_isNotExists    = Left ( token ; 12 ) = "NOT EXISTS (" ;
_isExists       = Left ( token ; 8  ) = "EXISTS (" ;
_isNotNull      = PatternCount ( token ; " IS NOT NULL" ) > 0 ;
_isNull         = PatternCount ( token ; " IS NULL" ) > 0 ;
_isNotInSub     = PatternCount ( token ; " NOT IN (SELECT" ) > 0 ;
_isInSub        = PatternCount ( token ; " IN (SELECT" ) > 0 ;
_isNotIn        = PatternCount ( token ; " NOT IN (" ) > 0 ;
_isIn           = PatternCount ( token ; " IN (" ) > 0 ;
_isNotBetween   = PatternCount ( token ; " NOT BETWEEN " ) > 0 ;
_isBetween      = PatternCount ( token ; " BETWEEN " ) > 0 ;
_isRaw          = Left ( token ; 1 ) = "(" ;
_isColumn       = Right ( token ; 1 ) = _dq ;
// --- Column extraction helpers ---
// For basic: token ends with " ?"
_stripRhsB  = Left ( token ; Length ( token ) - 2 ) ;
_lastDqB    = Position ( _stripRhsB ; _dq ; 1 ; PatternCount ( _stripRhsB ; _dq ) ) ;
_colBasic   = Left ( _stripRhsB ; _lastDqB ) ;
_opBasic    = Trim ( Middle ( _stripRhsB ; _lastDqB + 1 ; Length ( _stripRhsB ) ) ) ;
// For column type: "T1"."c1" op "T2"."c2"
_splitPosC  = Position ( token ; _dq & " " ; 1 ; 1 ) ;
_firstC     = Left ( token ; _splitPosC ) ;
_afterFirstC = Trim ( Middle ( token ; _splitPosC + 2 ; Length ( token ) ) ) ;
_opEndC     = Position ( _afterFirstC ; " " ; 1 ; 1 ) ;
_opC        = If ( _opEndC > 0 ; Left ( _afterFirstC ; _opEndC - 1 ) ; _afterFirstC ) ;
_secondC    = If ( _opEndC > 0 ; Trim ( Middle ( _afterFirstC ; _opEndC + 1 ; Length ( _afterFirstC ) ) ) ; "" ) ;
// For null/notNull: column is everything before " IS"
_isPos      = Position ( token ; " IS " ; 1 ; 1 ) ;
_colNull    = Left ( token ; _isPos - 1 ) ;
// For IN/NOT IN: column before " IN (" or " NOT IN ("
_inPos      = Position ( token ; " IN (" ; 1 ; 1 ) ;
_notInPos   = Position ( token ; " NOT IN (" ; 1 ; 1 ) ;
_colIn      = Left ( token ; _inPos - 1 ) ;
_colNotIn   = Left ( token ; _notInPos - 1 ) ;
// Value count for IN: count "?" inside the parens
_inValueCount    = PatternCount ( token ; "?" ) ;
_notInValueCount = PatternCount ( token ; "?" ) ;
// For BETWEEN / NOT BETWEEN
_betweenPos    = Position ( token ; " BETWEEN " ; 1 ; 1 ) ;
_notBetweenPos = Position ( token ; " NOT BETWEEN " ; 1 ; 1 ) ;
_colBetween    = Left ( token ; _betweenPos - 1 ) ;
_colNotBetween = Left ( token ; _notBetweenPos - 1 ) ;
// For EXISTS/NOT EXISTS: sql is inside the outer parens
_sqlExists    = Substitute ( Middle ( token ; 9  ; Length ( token ) - 9  ) ; Char ( 29 ) ; _restoreChar29 ) ;
_sqlNotExists = Substitute ( Middle ( token ; 13 ; Length ( token ) - 13 ) ; Char ( 29 ) ; _restoreChar29 ) ;
// For IN (subquery) / NOT IN (subquery)
_inSubPos    = Position ( token ; " IN (" ; 1 ; 1 ) ;
_colInSub    = Left ( token ; _inSubPos - 1 ) ;
_sqlInSub    = Substitute ( Middle ( token ; _inSubPos + 5 ; Length ( token ) - _inSubPos - 5 ) ; Char ( 29 ) ; _restoreChar29 ) ;
_notInSubPos = Position ( token ; " NOT IN (" ; 1 ; 1 ) ;
_colNotInSub = Left ( token ; _notInSubPos - 1 ) ;
_sqlNotInSub = Substitute ( Middle ( token ; _notInSubPos + 9 ; Length ( token ) - _notInSubPos - 9 ) ; Char ( 29 ) ; _restoreChar29 ) ;
// For raw: strip outer parens and restore Char(29)
_rawSql = Substitute ( Middle ( token ; 2 ; Length ( token ) - 2 ) ; Char ( 29 ) ; _restoreChar29 ) ;
// --- Build where object ---
_whereObj = Case (
	_isNotExists ;
		JSONSetElement ( "{}" ;
			[ "type" ; "notExists" ; JSONString ] ;
			[ "sql" ; _sqlNotExists ; JSONString ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isExists ;
		JSONSetElement ( "{}" ;
			[ "type" ; "exists" ; JSONString ] ;
			[ "sql" ; _sqlExists ; JSONString ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isNotNull ;
		JSONSetElement ( "{}" ;
			[ "type" ; "notNull" ; JSONString ] ;
			[ "column" ; _colNull ; JSONString ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isNull ;
		JSONSetElement ( "{}" ;
			[ "type" ; "null" ; JSONString ] ;
			[ "column" ; _colNull ; JSONString ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isNotInSub ;
		JSONSetElement ( "{}" ;
			[ "type" ; "notInSubquery" ; JSONString ] ;
			[ "column" ; _colNotInSub ; JSONString ] ;
			[ "sql" ; _sqlNotInSub ; JSONString ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isInSub ;
		JSONSetElement ( "{}" ;
			[ "type" ; "inSubquery" ; JSONString ] ;
			[ "column" ; _colInSub ; JSONString ] ;
			[ "sql" ; _sqlInSub ; JSONString ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isNotIn ;
		JSONSetElement ( "{}" ;
			[ "type" ; "notIn" ; JSONString ] ;
			[ "column" ; _colNotIn ; JSONString ] ;
			[ "valueCount" ; _notInValueCount ; JSONNumber ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isIn ;
		JSONSetElement ( "{}" ;
			[ "type" ; "in" ; JSONString ] ;
			[ "column" ; _colIn ; JSONString ] ;
			[ "valueCount" ; _inValueCount ; JSONNumber ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isNotBetween ;
		JSONSetElement ( "{}" ;
			[ "type" ; "notBetween" ; JSONString ] ;
			[ "column" ; _colNotBetween ; JSONString ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isBetween ;
		JSONSetElement ( "{}" ;
			[ "type" ; "between" ; JSONString ] ;
			[ "column" ; _colBetween ; JSONString ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isRaw ;
		JSONSetElement ( "{}" ;
			[ "type" ; "raw" ; JSONString ] ;
			[ "sql" ; _rawSql ; JSONString ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	_isColumn ;
		JSONSetElement ( "{}" ;
			[ "type" ; "column" ; JSONString ] ;
			[ "column" ; _firstC ; JSONString ] ;
			[ "operator" ; _opC ; JSONString ] ;
			[ "second" ; _secondC ; JSONString ] ;
			[ "boolean" ; boolean ; JSONString ]
			) ;
	// default: basic
	JSONSetElement ( "{}" ;
		[ "type" ; "basic" ; JSONString ] ;
		[ "column" ; _colBasic ; JSONString ] ;
		[ "operator" ; _opBasic ; JSONString ] ;
		[ "boolean" ; boolean ; JSONString ]
		)
	) ;
_q1 = JSONSetElement ( query ; "wheres[" & _whereCount & "]" ; _whereObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "whereCount" ; _whereCount + 1 ; JSONNumber )
] ;
_q2
)

// Iterates over a ¶-delimited list of WHERE condition tokens.
// Each token (after the first) starts with " AND " or " OR " as a boolean prefix.
// condList: output of QueryParseSplitBooleans with Char(28) replaced by ¶.
// condCount: ValueCount of condList.
// index: 1-based current position.
// Calls QueryParseWhereCondition for each trimmed condition.
Let
(
[
_raw = GetValue ( condList ; index ) ;
// Detect and strip boolean prefix
_isOr  = Left ( _raw ; 4 ) = " OR " ;
_isAnd = Left ( _raw ; 5 ) = " AND " ;
_boolean = If ( _isOr ; "or" ; "and" ) ;
_condition = Trim ( Case (
	_isAnd ; Middle ( _raw ; 6 ; Length ( _raw ) ) ;
	_isOr  ; Middle ( _raw ; 5 ; Length ( _raw ) ) ;
	_raw
	) ) ;
_q1 = QueryParseWhereCondition ( query ; _condition ; _boolean ) ;
_rest = If ( index < condCount ;
	QueryParseWheresIter ( _q1 ; condList ; condCount ; index + 1 ) ;
	_q1
	)
] ;
_rest
)

// Parses the WHERE clause from QueryToSQL output.
// Extracts the clause body via QueryParseClause (which uses the Char(29) trick).
// The body uses Char(29) as separator for every logical line-break that was
// originally ¶+4spaces.  QueryToSQL converts " AND " and " OR " to
// ¶+4spaces+AND+¶+4spaces, so they appear as {29}AND{29} and {29}OR{29}.
// Key fix: BETWEEN ? AND ? also becomes ?{29}AND{29}? — its inner AND is
// protected with Char(31) in place of the spaces so neither the {29}AND{29}
// reconstruction nor QueryParseSplitBooleans treats it as a condition boundary.
// Char(31) is restored to a space after splitting. Covers NOT BETWEEN as well,
// since "NOT BETWEEN ?" contains "BETWEEN ?".
// After reconstruction, applies depth-aware QueryParseSplitBooleans to handle
// parenthesised conditions (raw, exists, group) without splitting their internals.
Let
(
[
_body = QueryParseClause ( sql ; "WHERE" ) ;
// Protect BETWEEN/NOT BETWEEN: their inner AND must not become a condition boundary
_fixedBody = Substitute ( _body ;
	"BETWEEN ?" & Char ( 29 ) & "AND" & Char ( 29 ) & "?" ;
	"BETWEEN ?" & Char ( 31 ) & "AND" & Char ( 31 ) & "?" ) ;
// Reconstruct the WHERE text: {29}AND{29} → " AND ", {29}OR{29} → " OR "
_whereText = Substitute ( Substitute ( _fixedBody ;
	Char ( 29 ) & "AND" & Char ( 29 ) ; " AND " ) ;
	Char ( 29 ) & "OR" & Char ( 29 ) ; " OR " ) ;
// Depth-aware split: inserts Char(28) before each top-level AND/OR
_split = QueryParseSplitBooleans ( _whereText ; 0 ; 1 ; "" ) ;
// Convert to ¶-delimited list for GetValue iteration; restore protected BETWEEN spaces
_condList = Substitute ( _split ; [ Char ( 28 ) ; ¶ ] ; [ Char ( 31 ) ; " " ] ) ;
_condCount = ValueCount ( _condList )
] ;
If ( IsEmpty ( _body ) ;
	query ;
	QueryParseWheresIter ( query ; _condList ; _condCount ; 1 )
)
)

// Rebuilds outerQuery's bindings array as [prefixBindings...][suffixBindings...].
// prefixBindings is a subquery's bindings JSON array (written first because
// the subquery appears in FROM, before WHERE in SQL). suffixBindings is the
// outer query's existing bindings JSON array. Call with index = 0.
// On the final iteration writes the new bindingCount = prefixCount + suffixCount.
// Used by QueryFromSubquery to ensure correct ? placeholder order.
Let
(
[
_total = prefixCount + suffixCount ;
_value = If ( index < prefixCount ;
	JSONGetElement ( prefixBindings ; "[" & index & "]" ) ;
	JSONGetElement ( suffixBindings ; "[" & ( index - prefixCount ) & "]" )
	) ;
_q1 = JSONSetElement ( outerQuery ; "bindings[" & index & "]" ; _value ; JSONString )
];
If ( index + 1 < _total ;
	QueryPrependBindings ( _q1 ; prefixBindings ; prefixCount ; suffixBindings ; suffixCount ; index + 1 ) ;
// ELSE last element: write final bindingCount
	JSONSetElement ( _q1 ; "bindingCount" ; _total ; JSONNumber )
)
)

// Appends a CROSS JOIN (cartesian product) with no ON condition.
// table accepts a plain string, direct FM field reference, or GetFieldName() result.
Let
(
[
_joinCount = JSONGetElement ( query ; "joinCount" ) ;
_fqName = GetFieldName ( table ) ;
_tableName = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; table ) ;
_table = Quote (
	If ( PatternCount ( _tableName ; "::" ) ;
		Left ( _tableName ; Position ( _tableName ; "::" ; 1 ; 1 ) - 1 ) ;
	// ELSE
		_tableName
	)) ;
_joinObj = JSONSetElement ( "{}" ;
	[ "type" ; "cross" ; JSONString ] ;
	[ "table" ; _table ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "joins[" & _joinCount & "]" ; _joinObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "joinCount" ; _joinCount + 1 ; JSONNumber )
];
_q2
)

// Convenience function: sets LIMIT and OFFSET for a specific page number.
// page is 1-based. Equivalent to:
//   QueryLimit ( QueryOffset ( query ; (page - 1) * perPage ) ; perPage )
// Example: page=2, perPage=25 → FETCH FIRST 25 ROWS ONLY OFFSET 25 ROWS
Let
(
[
_offset = ( page - 1 ) * perPage ;
_q1 = JSONSetElement ( query ; "limit" ; perPage ; JSONNumber ) ;
_q2 = JSONSetElement ( _q1 ; "offset" ; _offset ; JSONNumber )
];
_q2
)

Let
(
[
_groupByCount = JSONGetElement ( query ; "groupByCount" ) ;
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col )
];
JSONSetElement (
	JSONSetElement ( query ; "groupBys[" & _groupByCount & "]" ; _column ; JSONString ) ;
	"groupByCount" ; _groupByCount + 1 ; JSONNumber
)
)

// Appends a raw SQL expression to the GROUP BY clause verbatim.
// Useful for function-based grouping such as YEAR(dateField).
// Example: QueryGroupByRaw ( query ; "YEAR(\"Invoice\".\"date\")" )
Let
(
[
_groupByCount = JSONGetElement ( query ; "groupByCount" ) ;
_rawObj = JSONSetElement ( "{}" ;
	[ "type" ; "raw" ; JSONString ] ;
	[ "sql" ; rawSql ; JSONString ]
	)
];
JSONSetElement (
	JSONSetElement ( query ; "groupBys[" & _groupByCount & "]" ; _rawObj ; JSONObject ) ;
	"groupByCount" ; _groupByCount + 1 ; JSONNumber
)
)

Let
(
[
_havingCount = JSONGetElement ( query ; "havingCount" ) ;
_bindingCount = JSONGetElement ( query ; "bindingCount" ) ;
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col ) ;
_havingObj = JSONSetElement ( "{}" ;
	[ "column" ; _column ; JSONString ] ;
	[ "operator" ; operator ; JSONString ] ;
	[ "boolean" ; "and" ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "havings[" & _havingCount & "]" ; _havingObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "havingCount" ; _havingCount + 1 ; JSONNumber ) ;
_q3 = JSONSetElement ( _q2 ; "bindings[" & _bindingCount & "]" ; value ; JSONString ) ;
_q4 = JSONSetElement ( _q3 ; "bindingCount" ; _bindingCount + 1 ; JSONNumber )
];
_q4
)

// Appends AND (rawSql) to the HAVING clause verbatim.
// bindings is an optional ¶-delimited list of values for any ? placeholders in rawSql.
// Leave bindings empty if rawSql contains no placeholders.
// Use QueryOrHavingRaw for OR prefix.
Let
(
[
_havingCount = JSONGetElement ( query ; "havingCount" ) ;
_valueCount = If ( IsEmpty ( bindings ) ; 0 ; ValueCount ( bindings ) ) ;
_havingObj = JSONSetElement ( "{}" ;
	[ "type" ; "raw" ; JSONString ] ;
	[ "sql" ; rawSql ; JSONString ] ;
	[ "boolean" ; "and" ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "havings[" & _havingCount & "]" ; _havingObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "havingCount" ; _havingCount + 1 ; JSONNumber ) ;
_q3 = If ( _valueCount > 0 ;
	QueryAppendBindings ( _q2 ; bindings ; _valueCount ; 1 ) ;
	_q2
	)
];
_q3
)

Let
(
[
_joinCount = JSONGetElement ( query ; "joinCount" ) ;
_fqName = GetFieldName ( table ) ;
_tableName = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; table ) ;
_table = Quote (
	If ( PatternCount ( _tableName ; "::" ) ;
		Left ( _tableName ; Position ( _tableName ; "::" ; 1 ; 1 ) - 1 ) ;
	// ELSE
		_tableName
	)) ;
_fqFirst = GetFieldName ( first ) ;
_first = QueryFieldFormat ( If ( Position ( _fqFirst ; "::" ; 1 ; 1 ) > 0 ; _fqFirst ; first ) ) ;
_fqSecond = GetFieldName ( second ) ;
_second = QueryFieldFormat ( If ( Position ( _fqSecond ; "::" ; 1 ; 1 ) > 0 ; _fqSecond ; second ) ) ;
_joinObj = JSONSetElement ( "{}" ;
	[ "type" ; "inner" ; JSONString ] ;
	[ "table" ; _table ; JSONString ] ;
	[ "first" ; _first ; JSONString ] ;
	[ "operator" ; operator ; JSONString ] ;
	[ "second" ; _second ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "joins[" & _joinCount & "]" ; _joinObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "joinCount" ; _joinCount + 1 ; JSONNumber )
];
_q2
)

Let
(
[
_joinCount = JSONGetElement ( query ; "joinCount" ) ;
_fqName = GetFieldName ( table ) ;
_tableName = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; table ) ;
_table = Quote (
	If ( PatternCount ( _tableName ; "::" ) ;
		Left ( _tableName ; Position ( _tableName ; "::" ; 1 ; 1 ) - 1 ) ;
	// ELSE
		_tableName
	)) ;
_fqFirst = GetFieldName ( first ) ;
_first = QueryFieldFormat ( If ( Position ( _fqFirst ; "::" ; 1 ; 1 ) > 0 ; _fqFirst ; first ) ) ;
_fqSecond = GetFieldName ( second ) ;
_second = QueryFieldFormat ( If ( Position ( _fqSecond ; "::" ; 1 ; 1 ) > 0 ; _fqSecond ; second ) ) ;
_joinObj = JSONSetElement ( "{}" ;
	[ "type" ; "left" ; JSONString ] ;
	[ "table" ; _table ; JSONString ] ;
	[ "first" ; _first ; JSONString ] ;
	[ "operator" ; operator ; JSONString ] ;
	[ "second" ; _second ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "joins[" & _joinCount & "]" ; _joinObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "joinCount" ; _joinCount + 1 ; JSONNumber )
];
_q2
)

Let
(
[
_fqName = GetFieldName ( table ) ;
_tableName = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; table ) ;
_table = Quote (
	If ( PatternCount ( _tableName ; "::" ) ;
		Left ( _tableName ; Position ( _tableName ; "::" ; 1 ; 1 ) - 1 ) ;
	// ELSE
		_tableName
	))
];
JSONSetElement ( "{}" ;
[ "table" ; _table ; JSONString ] ;
[ "selects" ; "*" ; JSONString ] ;
[ "selectKeys" ; "*" ; JSONString ] ;
[ "joins" ; "[]" ; JSONRaw ] ;
[ "joinCount" ; 0 ; JSONNumber ] ;
[ "wheres" ; "[]" ; JSONRaw ] ;
[ "whereCount" ; 0 ; JSONNumber ] ;
[ "groupBys" ; "[]" ; JSONRaw ] ;
[ "groupByCount" ; 0 ; JSONNumber ] ;
[ "havings" ; "[]" ; JSONRaw ] ;
[ "havingCount" ; 0 ; JSONNumber ] ;
[ "orderBys" ; "[]" ; JSONRaw ] ;
[ "orderByCount" ; 0 ; JSONNumber ] ;
[ "limit" ; "" ; JSONString ] ;
[ "offset" ; "" ; JSONString ] ;
[ "bindings" ; "[]" ; JSONRaw ] ;
[ "bindingCount" ; 0 ; JSONNumber ]
)
)

// Reconstructs a fmorm query object from a SQL string produced by QueryToSQL.
// sql     — SQL string as returned by QueryToSQL (pretty-printed, double-quoted identifiers).
// bindings — ¶-delimited list of binding values for each ? placeholder, in left-to-right order.
//            Pass "" if the SQL has no ? placeholders.
// Returns a query object equivalent to one built via builder calls; passable to QueryGet,
// QueryToSQL, or any builder function for further modification.
//
// Parsing contract: only handles QueryToSQL output format.
//   Each top-level keyword (SELECT, FROM, JOIN, WHERE, …) is at column 0 on its own line.
//   Child content is indented with exactly 4 spaces.
//   Identifiers are double-quoted ("Table"."Field").
//   Placeholders are ?.
//
// Known limitations:
//   UNION / UNION ALL — Phase 2 (union clauses are ignored; main query parses correctly).
//   Subquery round-trip — Phase 3 (FROM subquery, JOIN subquery stored as raw expressions).
//   Raw SQL with embedded AND/OR/IS NULL keywords may mis-detect condition type.
//   ~5,000-char WHERE limit from FM recursion cap on QueryParseSplitBooleans.
//   Bindings must be supplied by caller; they cannot be recovered from the SQL string.
Let
(
[
_norm = Substitute ( sql ; ¶ & "    " ; Char ( 29 ) ) ;
// --- FROM: extract table name ---
_fromBody = QueryParseClause ( sql ; "FROM" ) ;
_table = Trim ( _fromBody ) ;
// --- Initialise base query object from QueryNew so the structures cannot drift ---
// The parsed table is already in SQL form ("Table" or a subquery expression),
// so it overwrites the table QueryNew would quote rather than being passed in.
_base = JSONSetElement ( QueryNew ( "" ) ; "table" ; _table ; JSONString ) ;
// --- SELECT ---
_q1 = QueryParseSelects ( _base ; sql ) ;
// --- JOINs ---
_q2 = QueryParseJoins ( _q1 ; _norm ; 1 ) ;
// --- WHERE ---
_q3 = QueryParseWheres ( _q2 ; sql ) ;
// --- GROUP BY ---
_groupBody = QueryParseClause ( sql ; "GROUP BY" ) ;
_groupCols = Substitute ( _groupBody ; "," & Char ( 29 ) ; ¶ ) ;
_groupCount = If ( IsEmpty ( _groupBody ) ; 0 ; ValueCount ( _groupCols ) ) ;
_q4 = If ( _groupCount > 0 ;
	QueryParseGroupBys ( _q3 ; _groupCols ; _groupCount ; 1 ) ;
	_q3
	) ;
// --- HAVING ---
_q5 = QueryParseHavings ( _q4 ; sql ) ;
// --- ORDER BY ---
_orderBody = QueryParseClause ( sql ; "ORDER BY" ) ;
_orderCols = Substitute ( _orderBody ; "," & Char ( 29 ) ; ¶ ) ;
_orderCount = If ( IsEmpty ( _orderBody ) ; 0 ; ValueCount ( _orderCols ) ) ;
_q6 = If ( _orderCount > 0 ;
	QueryParseOrderBys ( _q5 ; _orderCols ; _orderCount ; 1 ) ;
	_q5
	) ;
// --- OFFSET ---
// Format in SQL: ¶OFFSET n ROWS  (no indented body — single-line clause)
_offsetMarker = ¶ & "OFFSET " ;
_offsetStart = Position ( sql ; _offsetMarker ; 1 ; 1 ) ;
_offsetNumStart = _offsetStart + Length ( _offsetMarker ) ;
_offsetEnd = Position ( sql ; " ROWS" ; _offsetNumStart ; 1 ) ;
_offsetVal = If ( _offsetStart > 0 and _offsetEnd > 0 ;
	Middle ( sql ; _offsetNumStart ; _offsetEnd - _offsetNumStart ) ;
	""
	) ;
_q7 = If ( not IsEmpty ( _offsetVal ) ;
	JSONSetElement ( _q6 ; "offset" ; _offsetVal ; JSONNumber ) ;
	_q6
	) ;
// --- FETCH FIRST (LIMIT) ---
// Format: ¶FETCH FIRST n ROWS ONLY
_fetchMarker = ¶ & "FETCH FIRST " ;
_fetchStart = Position ( sql ; _fetchMarker ; 1 ; 1 ) ;
_fetchNumStart = _fetchStart + Length ( _fetchMarker ) ;
_fetchEnd = Position ( sql ; " ROWS ONLY" ; _fetchNumStart ; 1 ) ;
_limitVal = If ( _fetchStart > 0 and _fetchEnd > 0 ;
	Middle ( sql ; _fetchNumStart ; _fetchEnd - _fetchNumStart ) ;
	""
	) ;
_q8 = If ( not IsEmpty ( _limitVal ) ;
	JSONSetElement ( _q7 ; "limit" ; _limitVal ; JSONNumber ) ;
	_q7
	) ;
// --- Bindings ---
// All ? placeholders are filled in order from the supplied bindings list.
_bindingCount = ValueCount ( bindings ) ;
_q9 = If ( _bindingCount > 0 ;
	QueryAppendBindings ( _q8 ; bindings ; _bindingCount ; 1 ) ;
	_q8
	)
] ;
_q9
)

// Appends OR column operator value to the HAVING clause. One binding is added.
// Must be used after QueryGroupBy.
// Use QueryHaving for AND HAVING.
Let
(
[
_havingCount = JSONGetElement ( query ; "havingCount" ) ;
_bindingCount = JSONGetElement ( query ; "bindingCount" ) ;
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col ) ;
_havingObj = JSONSetElement ( "{}" ;
	[ "column" ; _column ; JSONString ] ;
	[ "operator" ; operator ; JSONString ] ;
	[ "boolean" ; "or" ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "havings[" & _havingCount & "]" ; _havingObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "havingCount" ; _havingCount + 1 ; JSONNumber ) ;
_q3 = JSONSetElement ( _q2 ; "bindings[" & _bindingCount & "]" ; value ; JSONString ) ;
_q4 = JSONSetElement ( _q3 ; "bindingCount" ; _bindingCount + 1 ; JSONNumber )
];
_q4
)

// Appends OR (rawSql) to the HAVING clause verbatim.
// bindings is an optional ¶-delimited list of values for any ? placeholders in rawSql.
// Leave bindings empty if rawSql contains no placeholders.
// Use QueryHavingRaw for AND prefix.
Let
(
[
_havingCount = JSONGetElement ( query ; "havingCount" ) ;
_valueCount = If ( IsEmpty ( bindings ) ; 0 ; ValueCount ( bindings ) ) ;
_havingObj = JSONSetElement ( "{}" ;
	[ "type" ; "raw" ; JSONString ] ;
	[ "sql" ; rawSql ; JSONString ] ;
	[ "boolean" ; "or" ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "havings[" & _havingCount & "]" ; _havingObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "havingCount" ; _havingCount + 1 ; JSONNumber ) ;
_q3 = If ( _valueCount > 0 ;
	QueryAppendBindings ( _q2 ; bindings ; _valueCount ; 1 ) ;
	_q2
	)
];
_q3
)

Let
(
[
_whereCount = JSONGetElement ( query ; "whereCount" ) ;
_bindingCount = JSONGetElement ( query ; "bindingCount" ) ;
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col ) ;
_whereObj = JSONSetElement ( "{}" ;
	[ "type" ; "basic" ; JSONString ] ;
	[ "column" ; _column ; JSONString ] ;
	[ "operator" ; operator ; JSONString ] ;
	[ "boolean" ; "or" ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "wheres[" & _whereCount & "]" ; _whereObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "whereCount" ; _whereCount + 1 ; JSONNumber ) ;
_q3 = JSONSetElement ( _q2 ; "bindings[" & _bindingCount & "]" ; value ; JSONString ) ;
_q4 = JSONSetElement ( _q3 ; "bindingCount" ; _bindingCount + 1 ; JSONNumber )
];
_q4
)

// Appends OR column BETWEEN low AND high. Two bindings are added.
Let
(
[
_whereCount = JSONGetElement ( query ; "whereCount" ) ;
_bindingCount = JSONGetElement ( query ; "bindingCount" ) ;
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col ) ;
_whereObj = JSONSetElement ( "{}" ;
	[ "type" ; "between" ; JSONString ] ;
	[ "column" ; _column ; JSONString ] ;
	[ "boolean" ; "or" ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "wheres[" & _whereCount & "]" ; _whereObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "whereCount" ; _whereCount + 1 ; JSONNumber ) ;
_q3 = JSONSetElement ( _q2 ; "bindings[" & _bindingCount & "]" ; low ; JSONString ) ;
_q4 = JSONSetElement ( _q3 ; "bindingCount" ; _bindingCount + 1 ; JSONNumber ) ;
_q5 = JSONSetElement ( _q4 ; "bindings[" & ( _bindingCount + 1 ) & "]" ; high ; JSONString ) ;
_q6 = JSONSetElement ( _q5 ; "bindingCount" ; _bindingCount + 2 ; JSONNumber )
];
_q6
)

// Appends OR (inner conditions...) wrapping the WHERE conditions from groupedQuery.
// Build groupedQuery on any query object using QueryWhere / QueryOrWhere etc.
// Only the wheres and bindings of groupedQuery are used; its FROM/SELECT/etc. are ignored.
// Example: OR (status = ? OR priority = ?)
// Use QueryWhereGroup to prefix the group with AND instead of OR.
Let
(
[
_whereCount = JSONGetElement ( query ; "whereCount" ) ;
_groupWheres = JSONGetElement ( groupedQuery ; "wheres" ) ;
_groupWhereCount = JSONGetElement ( groupedQuery ; "whereCount" ) ;
_groupBindings = JSONGetElement ( groupedQuery ; "bindings" ) ;
_groupBindingCount = JSONGetElement ( groupedQuery ; "bindingCount" ) ;
_whereObj = JSONSetElement ( "{}" ;
	[ "type" ; "group" ; JSONString ] ;
	[ "wheres" ; _groupWheres ; JSONRaw ] ;
	[ "whereCount" ; _groupWhereCount ; JSONNumber ] ;
	[ "boolean" ; "or" ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "wheres[" & _whereCount & "]" ; _whereObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "whereCount" ; _whereCount + 1 ; JSONNumber ) ;
_q3 = If ( _groupBindingCount > 0 ;
	QueryMergeBindings ( _q2 ; _groupBindings ; _groupBindingCount ; 0 ) ;
	_q2
	)
];
_q3
)

// values is a ¶-delimited list of values.
// Appends OR column IN (?, ?, ...) and N bindings (one per value).
Let
(
[
_whereCount = JSONGetElement ( query ; "whereCount" ) ;
_valueCount = ValueCount ( values ) ;
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col ) ;
_whereObj = JSONSetElement ( "{}" ;
	[ "type" ; "in" ; JSONString ] ;
	[ "column" ; _column ; JSONString ] ;
	[ "valueCount" ; _valueCount ; JSONNumber ] ;
	[ "boolean" ; "or" ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "wheres[" & _whereCount & "]" ; _whereObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "whereCount" ; _whereCount + 1 ; JSONNumber ) ;
_q3 = QueryAppendBindings ( _q2 ; values ; _valueCount ; 1 )
];
_q3
)

// Appends OR column NOT BETWEEN low AND high. Two bindings are added.
Let
(
[
_whereCount = JSONGetElement ( query ; "whereCount" ) ;
_bindingCount = JSONGetElement ( query ; "bindingCount" ) ;
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col ) ;
_whereObj = JSONSetElement ( "{}" ;
	[ "type" ; "notBetween" ; JSONString ] ;
	[ "column" ; _column ; JSONString ] ;
	[ "boolean" ; "or" ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "wheres[" & _whereCount & "]" ; _whereObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "whereCount" ; _whereCount + 1 ; JSONNumber ) ;
_q3 = JSONSetElement ( _q2 ; "bindings[" & _bindingCount & "]" ; low ; JSONString ) ;
_q4 = JSONSetElement ( _q3 ; "bindingCount" ; _bindingCount + 1 ; JSONNumber ) ;
_q5 = JSONSetElement ( _q4 ; "bindings[" & ( _bindingCount + 1 ) & "]" ; high ; JSONString ) ;
_q6 = JSONSetElement ( _q5 ; "bindingCount" ; _bindingCount + 2 ; JSONNumber )
];
_q6
)

// Appends OR column IS NOT NULL.
Let
(
[
_whereCount = JSONGetElement ( query ; "whereCount" ) ;
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col ) ;
_whereObj = JSONSetElement ( "{}" ;
	[ "type" ; "notNull" ; JSONString ] ;
	[ "column" ; _column ; JSONString ] ;
	[ "boolean" ; "or" ; JSONString ]
	)
];
JSONSetElement (
	JSONSetElement ( query ; "wheres[" & _whereCount & "]" ; _whereObj ; JSONObject ) ;
	"whereCount" ; _whereCount + 1 ; JSONNumber
)
)

// Appends OR column IS NULL.
Let
(
[
_whereCount = JSONGetElement ( query ; "whereCount" ) ;
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col ) ;
_whereObj = JSONSetElement ( "{}" ;
	[ "type" ; "null" ; JSONString ] ;
	[ "column" ; _column ; JSONString ] ;
	[ "boolean" ; "or" ; JSONString ]
	)
];
JSONSetElement (
	JSONSetElement ( query ; "wheres[" & _whereCount & "]" ; _whereObj ; JSONObject ) ;
	"whereCount" ; _whereCount + 1 ; JSONNumber
)
)

// Appends OR (rawSql) inserting the expression verbatim into the WHERE clause.
// bindings is an optional ¶-delimited list of values for any ? placeholders in rawSql.
// Leave bindings empty if rawSql contains no placeholders.
// Use QueryWhereRaw for AND prefix.
Let
(
[
_whereCount = JSONGetElement ( query ; "whereCount" ) ;
_valueCount = If ( IsEmpty ( bindings ) ; 0 ; ValueCount ( bindings ) ) ;
_whereObj = JSONSetElement ( "{}" ;
	[ "type" ; "raw" ; JSONString ] ;
	[ "sql" ; rawSql ; JSONString ] ;
	[ "boolean" ; "or" ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "wheres[" & _whereCount & "]" ; _whereObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "whereCount" ; _whereCount + 1 ; JSONNumber ) ;
_q3 = If ( _valueCount > 0 ;
	QueryAppendBindings ( _q2 ; bindings ; _valueCount ; 1 ) ;
	_q2
	)
];
_q3
)

// direction defaults to "ASC" when empty.
Let
(
[
_orderByCount = JSONGetElement ( query ; "orderByCount" ) ;
_dir = If ( IsEmpty ( direction ) ; "ASC" ; Upper ( direction ) ) ;
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col ) ;
_orderByObj = JSONSetElement ( "{}" ;
	[ "column" ; _column ; JSONString ] ;
	[ "direction" ; _dir ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "orderBys[" & _orderByCount & "]" ; _orderByObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "orderByCount" ; _orderByCount + 1 ; JSONNumber )
];
_q2
)

// Appends a raw SQL expression to the ORDER BY clause verbatim.
// Useful for RAND(), CASE expressions, or function-based ordering.
// Example: QueryOrderByRaw ( query ; "RAND()" )
Let
(
[
_orderByCount = JSONGetElement ( query ; "orderByCount" ) ;
_orderByObj = JSONSetElement ( "{}" ;
	[ "type" ; "raw" ; JSONString ] ;
	[ "sql" ; rawSql ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "orderBys[" & _orderByCount & "]" ; _orderByObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "orderByCount" ; _orderByCount + 1 ; JSONNumber )
];
_q2
)

// Clears all ORDER BY clauses from the query.
// After calling this, new ORDER BY clauses can be added with QueryOrderBy.
JSONSetElement (
	JSONSetElement ( query ; "orderBys" ; "[]" ; JSONRaw ) ;
	"orderByCount" ; 0 ; JSONNumber
)

// Appends a RIGHT JOIN clause. table, first, and second accept plain strings,
// direct FM field references, or GetFieldName() results.
Let
(
[
_joinCount = JSONGetElement ( query ; "joinCount" ) ;
_fqName = GetFieldName ( table ) ;
_tableName = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; table ) ;
_table = Quote (
	If ( PatternCount ( _tableName ; "::" ) ;
		Left ( _tableName ; Position ( _tableName ; "::" ; 1 ; 1 ) - 1 ) ;
	// ELSE
		_tableName
	)) ;
_fqFirst = GetFieldName ( first ) ;
_first = QueryFieldFormat ( If ( Position ( _fqFirst ; "::" ; 1 ; 1 ) > 0 ; _fqFirst ; first ) ) ;
_fqSecond = GetFieldName ( second ) ;
_second = QueryFieldFormat ( If ( Position ( _fqSecond ; "::" ; 1 ; 1 ) > 0 ; _fqSecond ; second ) ) ;
_joinObj = JSONSetElement ( "{}" ;
	[ "type" ; "right" ; JSONString ] ;
	[ "table" ; _table ; JSONString ] ;
	[ "first" ; _first ; JSONString ] ;
	[ "operator" ; operator ; JSONString ] ;
	[ "second" ; _second ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "joins[" & _joinCount & "]" ; _joinObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "joinCount" ; _joinCount + 1 ; JSONNumber )
];
_q2
)

// Accepts a ¶-delimited list (e.g. from List() / GetFieldName()) or a
// comma-separated string. FileMaker fully-qualified names (Table::Field) are
// converted to quoted SQL dot notation ("Table"."Field"). Other expressions
// (*, COUNT(*), already-dotted names, raw SQL expressions, etc.) pass through
// unchanged — no separate QuerySelectRaw is needed.
// Calls are additive: the first call after QueryNew replaces the initial
// "*" sentinel; subsequent calls append to the existing column list.
Let
(
[
_normalized = Substitute ( Substitute ( columns ; ", " ; "¶" ) ; "," ; "¶" ) ;
_columnCount = ValueCount ( _normalized ) ;
_newSelects = QueryBuildSelects ( _normalized ; _columnCount ; 1 ) ;
_newKeys = QueryBuildSelectKeys ( _normalized ; _columnCount ; 1 ) ;
_existingSelects = JSONGetElement ( query ; "selects" ) ;
_existingKeys = JSONGetElement ( query ; "selectKeys" ) ;
_isWildcard = Exact ( _existingSelects ; "*" ) ;
_finalSelects = If ( _isWildcard ; _newSelects ; _existingSelects & ", " & _newSelects ) ;
_finalKeys = If ( _isWildcard ; _newKeys ; _existingKeys & ¶ & _newKeys ) ;
_q1 = JSONSetElement ( query ; "selects" ; _finalSelects ; JSONString )
];
JSONSetElement ( _q1 ; "selectKeys" ; _finalKeys ; JSONString )
)

// Assembles and returns the full SQL string without executing it.
// Useful for debugging. Bindings are represented as ? placeholders.
// Output is pretty-printed: each major clause on its own line,
// child items (fields, conditions, columns) indented with 4 spaces.
Let
(
[
_table = JSONGetElement ( query ; "table" ) ;
_selects = JSONGetElement ( query ; "selects" ) ;
_distinct = JSONGetElement ( query ; "distinct" ) ;
_joins = JSONGetElement ( query ; "joins" ) ;
_joinCount = JSONGetElement ( query ; "joinCount" ) ;
_wheres = JSONGetElement ( query ; "wheres" ) ;
_whereCount = JSONGetElement ( query ; "whereCount" ) ;
_groupBys = JSONGetElement ( query ; "groupBys" ) ;
_groupByCount = JSONGetElement ( query ; "groupByCount" ) ;
_havings = JSONGetElement ( query ; "havings" ) ;
_havingCount = JSONGetElement ( query ; "havingCount" ) ;
_orderBys = JSONGetElement ( query ; "orderBys" ) ;
_orderByCount = JSONGetElement ( query ; "orderByCount" ) ;
_limit = JSONGetElement ( query ; "limit" ) ;
_offset = JSONGetElement ( query ; "offset" ) ;
_unions = JSONGetElement ( query ; "unions" ) ;
_unionCount = JSONGetElement ( query ; "unionCount" ) ;
_in = "    " ;
_selectKeyword = If ( not IsEmpty ( _distinct ) and _distinct ; "SELECT DISTINCT" ; "SELECT" ) ;
_selectFields = Substitute ( _selects ; ", " ; "," & ¶ & _in ) ;
_joinRaw = If ( _joinCount > 0 ; QueryBuildJoins ( _joins ; _joinCount ; 0 ) ; "" ) ;
_joinSplit = Substitute ( Substitute ( Substitute ( Substitute ( _joinRaw ;
	" INNER JOIN " ; ¶ & "INNER JOIN " ) ;
	" LEFT JOIN " ; ¶ & "LEFT JOIN " ) ;
	" RIGHT JOIN " ; ¶ & "RIGHT JOIN " ) ;
	" CROSS JOIN " ; ¶ & "CROSS JOIN " ) ;
_joinClause = If ( _joinCount > 0 ;
	¶ & Substitute ( Substitute ( Substitute ( Substitute ( _joinSplit ;
		"INNER JOIN " ; "INNER JOIN" & ¶ & _in ) ;
		"LEFT JOIN " ; "LEFT JOIN" & ¶ & _in ) ;
		"RIGHT JOIN " ; "RIGHT JOIN" & ¶ & _in ) ;
		"CROSS JOIN " ; "CROSS JOIN" & ¶ & _in ) ;
	""
) ;
_whereRaw = If ( _whereCount > 0 ; QueryBuildWheres ( _wheres ; _whereCount ; 0 ) ; "" ) ;
_whereClause = If ( _whereCount > 0 ;
	¶ & "WHERE" & ¶ & _in & Substitute ( Substitute ( _whereRaw ; " AND " ; ¶ & _in & "AND" & ¶ & _in ) ; " OR " ; ¶ & _in & "OR" & ¶ & _in ) ;
	""
) ;
_groupByRaw = If ( _groupByCount > 0 ; QueryBuildGroupBys ( _groupBys ; _groupByCount ; 0 ) ; "" ) ;
_groupByClause = If ( _groupByCount > 0 ;
	¶ & "GROUP BY" & ¶ & _in & Substitute ( _groupByRaw ; ", " ; "," & ¶ & _in ) ;
	""
) ;
_havingRaw = If ( _havingCount > 0 ; QueryBuildHavings ( _havings ; _havingCount ; 0 ) ; "" ) ;
_havingClause = If ( _havingCount > 0 ;
	¶ & "HAVING" & ¶ & _in & Substitute ( Substitute ( _havingRaw ; " AND " ; ¶ & _in & "AND" & ¶ & _in ) ; " OR " ; ¶ & _in & "OR" & ¶ & _in ) ;
	""
) ;
_orderByRaw = If ( _orderByCount > 0 ; QueryBuildOrderBys ( _orderBys ; _orderByCount ; 0 ) ; "" ) ;
_orderByClause = If ( _orderByCount > 0 ;
	¶ & "ORDER BY" & ¶ & _in & Substitute ( _orderByRaw ; ", " ; "," & ¶ & _in ) ;
	""
) ;
_offsetClause = If ( not IsEmpty ( _offset ) ; ¶ & "OFFSET " & _offset & " ROWS" ; "" ) ;
_limitClause = If ( not IsEmpty ( _limit ) ; ¶ & "FETCH FIRST " & _limit & " ROWS ONLY" ; "" ) ;
_unionClause = If ( not IsEmpty ( _unionCount ) and _unionCount > 0 ;
	QueryBuildUnions ( _unions ; _unionCount ; 0 ) ;
	""
)
];
_selectKeyword & ¶ & _in & _selectFields &
¶ & "FROM" & ¶ & _in & _table &
_joinClause &
_whereClause &
_groupByClause &
_havingClause &
_orderByClause &
_offsetClause &
_limitClause &
_unionClause
)

// Replaces the FROM table with a derived table: FROM (SELECT ...) alias.
// The table name set in QueryNew is discarded and replaced by the subquery
// expression. alias is a plain SQL identifier — use a simple string like "sub".
// The subquery's bindings are prepended to any existing outer bindings because
// the FROM clause appears before WHERE in the SQL string, so its ? placeholders
// must come first in the bindings array for ExecuteSQL to match them correctly.
// NOTE: Derived tables (subqueries in FROM) are functional in FileMaker 19.x
// but are not formally documented by Claris. Test in your target FM version.
// Avoid QueryLimit / QueryOffset on the inner query — FETCH FIRST inside
// a subquery is not supported in all FM versions.
Let
(
[
_subSql = QueryToSQL ( subquery ) ;
_derivedTable = "(" & _subSql & ") " & alias ;
_subBindings = JSONGetElement ( subquery ; "bindings" ) ;
_subBindingCount = JSONGetElement ( subquery ; "bindingCount" ) ;
_outerBindings = JSONGetElement ( outerQuery ; "bindings" ) ;
_outerBindingCount = JSONGetElement ( outerQuery ; "bindingCount" ) ;
_q1 = JSONSetElement ( outerQuery ; "table" ; _derivedTable ; JSONString ) ;
_q2 = If ( _subBindingCount > 0 ;
	QueryPrependBindings ( _q1 ; _subBindings ; _subBindingCount ; _outerBindings ; _outerBindingCount ; 0 ) ;
	_q1
	)
];
_q2
)

// Executes the assembled query via ExecuteSQL using Evaluate to
// dynamically bind the stored parameter values.
// Returns "" if ExecuteSQL returns an error (result starting with "?").
Let
(
[
_sql = QueryToSQL ( query ) ;
_bindings = JSONGetElement ( query ; "bindings" ) ;
_bindingCount = JSONGetElement ( query ; "bindingCount" ) ;
_bindingArgs = QueryBuildBindingArgs ( _bindings ; _bindingCount ; 0 ) ;
_exprBase = "ExecuteSQL ( " & Quote ( _sql ) & " ; " & Quote ( fieldSeparator ) & " ; " & Quote ( rowSeparator ) ;
_expr = _exprBase & If ( _bindingCount > 0 ; " ; " & _bindingArgs ; "" ) & " )" ;
_result = Evaluate ( _expr )
];
If ( Left ( _result ; 1 ) = "?" ; "" ; _result )
)

// Executes SELECT AVG(column) for the assembled query and returns the average as a number.
// column accepts Table::Field references, GetFieldName() strings, or SQL expressions.
// The original query object is not modified.
// Returns 0 on error or empty result.
Let
(
[
_fqName = GetFieldName ( column ) ;
_col = If ( Position ( _fqName ; "::" ; 1 ; 1 ) > 0 ; _fqName ; column ) ;
_column = QueryFieldFormat ( _col ) ;
_q = JSONSetElement ( query ; "selects" ; "AVG(" & _column & ")" ; JSONString ) ;
_result = QueryGet ( _q ; ¶ ; Char ( 28 ) )
];
GetAsNumber ( GetValue ( _result ; 1 ) )
)

// Executes SELECT COUNT(*) for the assembled query and returns the count as a number.
// The original query object is not modified.
// Returns 0 on error or empty result.
Let
(
[
_q = JSONSetElement ( query ; "selects" ; "COUNT(*)" ; JSONString ) ;
_result = QueryGet ( _q ; ¶ ; Char ( 28 ) )
];
GetAsNumber ( GetValue ( _result ; 1 ) )
)

// Executes the query and returns results as a JSON array of objects.
// Property names are derived automatically from the selectKeys stored in the
// query object, which QuerySelect populates from the original column input.
// Returns "[]" when the query produces no rows or an error.
Let
(
[
_keys = JSONGetElement ( query ; "selectKeys" ) ;
_keyCount = ValueCount ( _keys ) ;
_rawResult = QueryGet ( query ; Char ( 28 ) ; "¶" ) ;
_rowCount = If ( IsEmpty ( _rawResult ) ; 0 ; ValueCount ( _rawResult ) )
];
If ( _rowCount = 0 ;
	"[]" ;
// ELSE
	QueryBuildJsonRows ( "[]" ; _rawResult ; _rowCount ; _keys ; _keyCount ; 1 )
)
)

// Appends INNER JOIN (SELECT ...) alias ON first operator second.
// alias is a plain SQL identifier string (e.g. "sub").
// first and second accept Table::Field references, GetFieldName() strings,
// or plain SQL expressions for the ON condition.
// The subquery's bindings are appended to the outer query's bindings.
// IMPORTANT: Call this before adding WHERE conditions to ensure correct
// binding order (JOIN bindings must precede WHERE bindings in the SQL).
// NOTE: JOIN subqueries require FileMaker 17+.
// Use QueryLeftJoinSub for a LEFT JOIN variant.
Let
(
[
_joinCount = JSONGetElement ( query ; "joinCount" ) ;
_subSql = QueryToSQL ( subquery ) ;
_subBindings = JSONGetElement ( subquery ; "bindings" ) ;
_subBindingCount = JSONGetElement ( subquery ; "bindingCount" ) ;
_fqFirst = GetFieldName ( first ) ;
_first = QueryFieldFormat ( If ( Position ( _fqFirst ; "::" ; 1 ; 1 ) > 0 ; _fqFirst ; first ) ) ;
_fqSecond = GetFieldName ( second ) ;
_second = QueryFieldFormat ( If ( Position ( _fqSecond ; "::" ; 1 ; 1 ) > 0 ; _fqSecond ; second ) ) ;
_joinObj = JSONSetElement ( "{}" ;
	[ "type" ; "subJoin" ; JSONString ] ;
	[ "sql" ; _subSql ; JSONString ] ;
	[ "alias" ; alias ; JSONString ] ;
	[ "first" ; _first ; JSONString ] ;
	[ "operator" ; operator ; JSONString ] ;
	[ "second" ; _second ; JSONString ]
	) ;
_q1 = JSONSetElement ( query ; "joins[" & _joinCount & "]" ; _joinObj ; JSONObject ) ;
_q2 = JSONSetElement ( _q1 ; "joinCount" ; _joinCount + 1 ; JSONNumber ) ;
_q3 = If ( _subBindingCount > 0 ;
	QueryMergeBindings ( _q2 ; _subBindings ; _subBindingCount ; 0 ) ;
	_q2
	)
];
_q3
)

